mapper.select:

where r.is_delete = 0

    and p.partner_name like concat('%', #{partnerName}, '%')


    and r.support_type = #{supportType}


    and r.publish_status = #{publishStatus}


    and r.support_date >= #{supportDateBegin}


    and r.support_date <= #{supportDateEnd}

order by r.sort_order desc, r.support_date desc, r.create_time desc, r.id desc

mapper.insert:
insert into basket_partner_support_record (
    partner_id, support_type, support_amount, support_date, public_description,
    publish_status, sort_order, create_by, create_time, update_by, update_time, is_delete
) values (
    #{partnerId}, #{supportType}, #{supportAmount}, #{supportDate}, #{publicDescription},
    #{publishStatus}, #{sortOrder}, #{createBy}, #{createTime}, #{updateBy}, #{updateTime}, #{isDelete}
)

mapper.update:
update basket_partner_support_record
set publish_status = #{toStatus}, update_time = now()
where id = #{id} and is_delete = 0 and publish_status = #{fromStatus}
